<script>
 import {invalidateAll} from '$app/navigation';import {onMount} from 'svelte';import Icon from './Icon.svelte';import EnergyFlow from './EnergyFlow.svelte';import HistoryChart from './HistoryChart.svelte';import {formatValue,formatTime,freshness} from '$lib/energy';
 let {data,preview=false}=$props();let refreshing=$state(false);let refreshError=$state(false);
 let metrics=$derived(data.snapshot?.metrics || {});
 let stale=$derived(Object.values(metrics).some(m=>m?.freshness==='stale'||m?.freshness==='invalid'));
 const messages={not_configured:['Awaiting connection','Your residence is registered. The GridUbuntu team is preparing its secure energy connection.'],no_assignment:['Your invitation is active','A residence has not been assigned to this account yet. Please contact your GridUbuntu team.'],database_unavailable:['Your residence is temporarily unavailable','We could not load your assigned residence. Try again or contact support.'],unavailable:['Energy connection unavailable','We could not retrieve the latest provider data. No current readings are being assumed.'],awaiting_verification:['Connection awaiting verification','GridUbuntu is checking the installation’s readings against Victron before making them available here.'],partial:['Some readings are unavailable','Part of the provider response could not be retrieved. Available readings retain their original reporting times.']};
 async function refresh(){if(preview)return;refreshing=true;refreshError=false;try{await invalidateAll();}catch{refreshError=true;}finally{refreshing=false;}}
 onMount(()=>{if(preview)return;const id=setInterval(()=>{if(document.visibilityState==='visible')refresh();},60000);return()=>clearInterval(id);});
 function power(m){return m?.value===undefined||m?.value===null?'—':formatValue(m.value/1000,'',2);}
</script>
<div class="page-heading"><div><div class="breadcrumb">MY RESIDENCE <span>/</span> OVERVIEW</div><h1>{data.node?.display_name || 'Your energy overview'}</h1><p>{data.node?.reference || 'Residence assignment pending'} <span>·</span> {data.node?.location_label || 'Zimbabwe'} <span>·</span> {preview?'Illustrative system':'Residential solar & storage'}</p></div><button class="refresh-button" onclick={refresh} disabled={refreshing||preview}><Icon name="refresh" size={16}/>{refreshing?'Refreshing…':'Refresh'}</button></div>
<div class="connection-line"><span class:stale class:connected={data.status==='connected'&&!stale} class="connection-badge"><i></i>{preview?'Sample readings':stale?'Readings delayed':data.status==='connected'?'Provider connected':data.status==='partial'?'Partial connection':'Connection pending'}</span><span>{preview?'Illustrative reporting time':'Oldest displayed reading'}: {formatTime(data.snapshot?.reportedAt)}</span></div>
{#if messages[data.status]}<div class="notice"><Icon name="info"/><div><strong>{messages[data.status][0]}</strong><p>{messages[data.status][1]}</p></div></div>{/if}{#if stale}<div class="notice warning" role="status"><Icon name="info"/><div><strong>These readings may be out of date.</strong><p>At least one reading is more than 15 minutes old or has an invalid future timestamp. Check each reading’s reporting time.</p></div></div>{/if}{#if refreshError}<p class="form-error" role="alert">The page could not refresh. Try again.</p>{/if}
<section class="metric-cards" aria-label="Current energy readings"><article class="metric-card"><div class="metric-label"><span>Solar generation</span><span class="metric-icon amber"><Icon name="sun"/></span></div><div class="metric-value">{power(metrics.solar)} <small>kW</small></div><div class="metric-bottom"><span>Reported solar power</span><span>{metrics.solar?formatTime(metrics.solar.reportedAt):'Not available'}</span></div></article><article class="metric-card"><div class="metric-label"><span>Home consumption</span><span class="metric-icon"><Icon name="home"/></span></div><div class="metric-value">{power(metrics.consumption)} <small>kW</small></div><div class="metric-bottom"><span>Reported household load</span><span>{metrics.consumption?formatTime(metrics.consumption.reportedAt):'Not available'}</span></div></article><article class="metric-card battery-card"><div class="metric-label"><span>Battery charge</span><span class="metric-icon"><Icon name="battery"/></span></div><div class="metric-value">{formatValue(metrics.batterySoc?.value,'',0)} <small>%</small></div><div class="battery-track"><span style:width={`${Math.max(0,Math.min(100,metrics.batterySoc?.value||0))}%`}></span></div><div class="metric-bottom"><span>{metrics.batteryPower?metrics.batteryPower.value>0?'Charging':metrics.batteryPower.value<0?'Discharging':'Idle':'State unavailable'}</span><span>{metrics.batterySoc?formatTime(metrics.batterySoc.reportedAt):'Not available'}</span></div></article></section>
<div class="overview-grid"><section class="panel flow-panel"><div class="panel-heading"><div><span class="overline">YOUR SYSTEM AT A GLANCE</span><h2>Where your energy is flowing</h2></div><span class="panel-tag">{preview?'Sample':'Latest reported'}</span></div><EnergyFlow {metrics}/></section><section class="panel today-panel"><div class="panel-heading"><div><span class="overline">TODAY · CAT</span><h2>The day in energy</h2></div><Icon name="history"/></div><div class="today-total"><span><i class="solar-key"></i>Solar generated</span><strong>{formatValue(data.history?.totals?.solar,'',2)} <small>kWh</small></strong></div><div class="today-total"><span><i class="usage-key"></i>Energy consumed</span><strong>{formatValue(data.history?.totals?.consumption,'',2)} <small>kWh</small></strong></div><div class="today-secondary"><div><span>Grid import</span><strong>{formatValue(data.history?.totals?.gridImport,'kWh',2)}</strong></div><div><span>Grid export</span><strong>{formatValue(data.history?.totals?.gridExport,'kWh',2)}</strong></div></div><a class="panel-link" href={preview?'/portal-preview?view=history':'/portal/history'}>Explore energy history <span>→</span></a></section></div>
<section class="panel history-panel"><div class="panel-heading"><div><span class="overline">GENERATION & CONSUMPTION</span><h2>Your energy through the day</h2></div><a class="quiet-link" href={preview?'/portal-preview?view=history':'/portal/history'}>View history →</a></div><HistoryChart history={data.history}/></section>
<div class="bottom-panels"><section class="panel"><div class="panel-heading"><div><span class="overline">INSTALLATION HEALTH</span><h2>Stay connected to your system</h2></div><Icon name="system"/></div><div class="health-row"><span>Data connection</span><strong>{preview?'Sample system':data.status==='connected'?'Responding':data.status==='partial'?'Partially responding':'Awaiting connection'}</strong></div><div class="health-row"><span>Device information</span><strong>{data.devices?.length?`${data.devices.length} devices reported`:'Not yet available'}</strong></div><a class="panel-link" href={preview?'/portal-preview?view=system':'/portal/system'}>View system details <span>→</span></a></section><section class="community-note"><span class="overline">THE POWER OF UBUNTU</span><h2>Your energy,<br/>part of something bigger.</h2><p>Understanding how we generate and use power is the first step towards a stronger energy community.</p><a href="/about">Why GridUbuntu <span>↗</span></a></section></div>
